#!/usr/bin/env python3
"""Compile actual CollisionState against the built mod/native26.3, then use real bootstrapped block states."""
from pathlib import Path
import subprocess,tempfile,os,json,hashlib
r=Path(__file__).resolve().parents[2];jdk=Path(os.environ.get('JAVA_HOME',str(Path.home()/'jdk25')))/'bin'
jar=r/'build/libs/meshac-26.3-2.9.7.28-meshac-0.1.0.jar';native=next((Path.home()/'.gradle-meshac/caches/fabric-loom/minecraftMaven/net/minecraft/minecraft-merged-deobf/26.3').glob('*.jar'))
cp=[str(jar),str(native)]+[str(p) for root in [Path('/tmp/meshac-smoke-26.3/server/libraries'),Path('/tmp/meshac-smoke-26.3/observer/fabric-api')] for p in root.rglob('*.jar')]+[str(p) for p in (Path.home()/'.gradle-meshac/caches/modules-2/files-2.1/net.fabricmc/fabric-loader').rglob('*.jar') if 'sources' not in p.name]
test='''public class GroundMaterialsTest {static void check(boolean b,String s){if(!b)throw new AssertionError(s);}public static void main(String[]args){net.minecraft.SharedConstants.tryDetectVersion();net.minecraft.server.Bootstrap.bootStrap();var c=new dev.meshac.player.CollisionState(null);var air=net.minecraft.world.level.block.Blocks.AIR.defaultBlockState();var slime=net.minecraft.world.level.block.Blocks.SLIME_BLOCK.defaultBlockState();var stone=net.minecraft.world.level.block.Blocks.STONE.defaultBlockState();check(c.getSubGroundMaterial()==null&&c.getDeepGroundMaterial()==null,"missing samples replaced by guessed block");c.setGroundMaterial(air);c.setSubGroundMaterial(slime);c.setDeepGroundMaterial(stone);check(c.getSubGroundMaterial()==slime,"sub-ground setter does not feed classifier/getter field");check(c.getDeepGroundMaterial()==stone,"deep-ground setter does not feed classifier/getter field");check(c.isNearGroundWide(),"solid sub-ground not classified from authoritative sample");c.setSubGroundMaterial(air);c.setDeepGroundMaterial(air);check(!c.isNearGroundWide(),"all-air samples classified as ground");c.setDeepGroundMaterial(stone);check(c.isNearGroundWide(),"deep-ground update stale or disconnected from reader");c.setSubGroundMaterial(null);check(c.getSubGroundMaterial()==null&&!c.isNearGroundWide(),"missing sample did not remain missing/fail-closed");System.out.println("GroundMaterialsTest PASS actual CollisionState and real native block states, no server/thread execution");}}'''
with tempfile.TemporaryDirectory(prefix='meshac-ground-') as d:
 t=Path(d);p=t/'GroundMaterialsTest.java';p.write_text(test);source=r/'src/main/java/dev/meshac/player/CollisionState.java';out=Path(os.environ.get('MESHAC_PREP_OUTPUT','/tmp/meshac-ground-materials'));out.mkdir(parents=True,exist_ok=True)
 (out/'inputs.json').write_text(json.dumps({'CollisionStateSHA256':hashlib.sha256(source.read_bytes()).hexdigest(),'builtJarSHA256':hashlib.sha256(jar.read_bytes()).hexdigest(),'nativeJarSHA256':hashlib.sha256(native.read_bytes()).hexdigest(),'testSHA256':hashlib.sha256(test.encode()).hexdigest()},indent=2)+'\n')
 subprocess.run([str(jdk/'javac'),'-proc:none','-cp',':'.join(cp),'-d',str(t),str(source),str(p)],check=True)
 subprocess.run([str(jdk/'java'),'-cp',str(t)+':'+':'.join(cp),'GroundMaterialsTest'],check=True)
